from dataclasses import dataclass

@dataclass
class Food:
    name: str
    sugar_g: float
    sodium_mg: float


def evaluate_for_hypertension(food: Food) -> str:
    if food.sodium_mg > 400:
        return "limit"
    return "ok"

type Verdict = "recommend" | "caution" | "avoid"

export function mergeVerdicts(v: Verdict[]): Verdict {
  if (v.includes("avoid")) return "avoid"
  if (v.includes("caution")) return "caution"
  return "recommend"
}
